package cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice;

import cn.nebulaedata.cccs.nebuwork.backend.api.agent.*;
import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice.ServiceSupport.*;

@Service
public class ServiceOperations {
    final WorkbenchServices services;final ServiceAccess access;final ServiceExecutions executions;final AgentStore db;final ObjectMapper json;
    public ServiceOperations(WorkbenchServices services,ServiceAccess access,ServiceExecutions executions){this.services=services;this.access=access;this.executions=executions;this.db=services.db;this.json=services.json;}
    public Object invoke(ServiceAccess.Principal p,String wb,String capability,JsonNode body,String key,String channel){requestKey(key);fields(body,"input","projectId","releaseId","instanceId");require(body.has("input"),422,"需要业务输入 input");String project=text(body,"projectId",128);p.allow(wb,"capabilities",capability);p.allow(wb,"projects",project);services.project(p.owner,wb,project,true);String id="so-"+hash(p.owner+":"+p.app+":"+wb+":"+key).substring(0,48),digest=hash(capability+":"+fingerprint(json,body));
        Map<String,Object> old=db.one("SELECT * FROM nw_service_operation WHERE id=?",id);if(old!=null){require(digest.equals(str(old,"request_hash")),409,"同一请求编号不能调用不同内容");return get(p,wb,id);}
        Map<String,Object> release=services.active(p,wb,body.path("releaseId").asText(""));JsonNode definition=parse(json,release.get("definition_json")),c=item(definition,"capabilities",capability);require(p.browser&&channel.equals("test")||c.path("channels").path(channel).asBoolean(),403,"此入口未开放该能力");require(contains(c.path("projectIds"),project),403,"项目不在能力授权范围");
        if(channel.equals("page")){Map<String,Object> instance=instance(p,wb,text(body,"instanceId",128));require(str(instance,"release_id").equals(str(release,"id"))&&project.equals(str(instance,"project_id")),403,"页面上下文不匹配");require(contains(item(definition,"pages",str(instance,"page_key")).path("capabilities"),capability),403,"页面未声明此能力");}
        schema(c.path("inputSchema"),body.get("input"));
        db.update("INSERT INTO nw_service_operation(id,owner_id,workbench_id,app_id,release_id,capability_key,project_id,request_key,request_hash,input_json,source_channel,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,'pending') ON DUPLICATE KEY UPDATE id=id",id,p.owner,wb,p.app,release.get("id"),capability,project,key,digest,body.get("input").toString(),channel);
        Map<String,Object> inserted=row(id);require(digest.equals(str(inserted,"request_hash")),409,"请求编号冲突");if(c.path("binding").path("type").asText().equals("platform"))dispatch(id);return get(p,wb,id);
    }
    Map<String,Object> row(String id){Map<String,Object> r=db.one("SELECT * FROM nw_service_operation WHERE id=?",id);require(r!=null,404,"服务调用不存在");return r;}
    ServiceAccess.Principal current(Map<String,Object> r){String app=str(r,"app_id");if(app.equals("browser"))return new ServiceAccess.Principal(str(r,"owner_id"),app,str(r,"workbench_id"),json.createObjectNode(),true);Map<String,Object> a=access.application(app);require(Boolean.TRUE.equals(a.get("enabled"))&&str(a,"owner_id").equals(str(r,"owner_id")),403,"应用已撤销");return new ServiceAccess.Principal(str(a,"owner_id"),app,str(a,"workbench_id"),parse(json,a.get("scope_json")),false);}
    JsonNode authorized(ServiceAccess.Principal p,String wb,Map<String,Object> r){require(p.owner.equals(str(r,"owner_id"))&&wb.equals(str(r,"workbench_id"))&&(p.browser||p.app.equals(str(r,"app_id"))),404,"调用不存在");p.allow(wb,"capabilities",str(r,"capability_key"));p.allow(wb,"projects",str(r,"project_id"));services.project(p.owner,wb,str(r,"project_id"),false);Map<String,Object> release=services.active(p,wb,str(r,"release_id"));JsonNode c=item(parse(json,release.get("definition_json")),"capabilities",str(r,"capability_key"));require(contains(c.path("projectIds"),str(r,"project_id")),403,"项目授权已变化");return c;}
    public Object get(ServiceAccess.Principal p,String wb,String id){Map<String,Object> r=row(id);authorized(p,wb,r);return view(r);}
    Object view(Map<String,Object> r){return map("id",r.get("id"),"operationId",r.get("id"),"releaseId",r.get("release_id"),"capability",r.get("capability_key"),"projectId",r.get("project_id"),"status",r.get("state"),"targetId",r.get("target_id"),"source",r.get("source_channel"),"applicationId",r.get("app_id"),"usage",r.get("usage_json")==null?map("totalTokens",null,"usageKnown",false,"unavailable",true):parse(json,r.get("usage_json")),"revision",r.get("revision"),"result",r.get("result_json")==null?null:parse(json,r.get("result_json")),"error",r.get("error_message"),"updatedAt",Objects.toString(r.get("updated_at"),""));}
    public Object list(String owner,String wb){services.owned(owner,wb);List<Object> result=new ArrayList<>();for(Map<String,Object> r:db.rows("SELECT * FROM nw_service_operation WHERE owner_id=? AND workbench_id=? ORDER BY created_at DESC LIMIT 100",owner,wb))result.add(view(r));return result;}
    public Object events(ServiceAccess.Principal p,String wb,String id,long after){get(p,wb,id);List<Object> result=new ArrayList<>();for(Map<String,Object> e:db.rows("SELECT * FROM nw_service_event WHERE operation_id=? AND id>? ORDER BY id LIMIT 100",id,Math.max(0,after)))result.add(map("id",e.get("id"),"data",parse(json,e.get("event_json"))));return result;}
    private void event(String id){Map<String,Object> r=row(id);db.update("INSERT INTO nw_service_event(operation_id,event_json) VALUES(?,?)",id,json.valueToTree(view(r)).toString());}
    void state(String id,String next,JsonNode result,String error){Map<String,Object> r=row(id);if(Arrays.asList("succeeded","failed","cancelled").contains(str(r,"state"))&&!next.equals(str(r,"state")))return;if(next.equals(str(r,"state"))&&Objects.equals(error,r.get("error_message"))&&(result==null||result.toString().equals(str(r,"result_json"))))return;String message=error==null?null:error.substring(0,Math.min(1900,error.length()));if(db.update("UPDATE nw_service_operation SET state=?,result_json=?,error_message=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND revision=?",next,result==null?null:result.toString(),message,id,r.get("revision"))==1)event(id);}
    void dispatch(String id){if(db.update("UPDATE nw_service_operation SET state='dispatching',updated_at=CURRENT_TIMESTAMP WHERE id=? AND state='pending'",id)!=1)return;Map<String,Object> r=row(id);try{ServiceAccess.Principal p=current(r);JsonNode c=authorized(p,str(r,"workbench_id"),r),input=parse(json,r.get("input_json"));services.project(p.owner,str(r,"workbench_id"),str(r,"project_id"),true);String type=c.path("binding").path("type").asText();
            if(type.equals("platform")){JsonNode result=json.valueToTree(executions.platform(p.owner,str(r,"project_id"),c.path("binding"),input));schema(c.path("outputSchema"),result);state(id,"succeeded",result,null);}
            else{JsonNode snapshot=parse(json,services.release(p.owner,str(r,"workbench_id"),str(r,"release_id")).get("execution_json")).path(str(r,"capability_key"));if(type.equals("agent"))db.update("UPDATE nw_service_operation SET target_id=? WHERE id=?","task-"+hash(p.owner+":"+str(r,"project_id")+":"+id).substring(0,40),id);String target=executions.start(p.owner,str(r,"project_id"),c,snapshot,id,input);require(!target.isEmpty(),502,"执行引擎未返回目标任务");db.update("UPDATE nw_service_operation SET target_id=? WHERE id=?",target,id);state(id,"running",null,null);}
        }catch(ApiException e){state(id,e.status>=500?"interrupted":"failed",null,e.getMessage());}catch(Exception e){state(id,"interrupted",null,"执行结果待核对，请查询原操作");}}
    public void refresh(String id){Map<String,Object> r=row(id);if(!Arrays.asList("running","waiting_input").contains(str(r,"state")))return;try{JsonNode c=authorized(current(r),str(r,"workbench_id"),r);String target=str(r,"target_id"),type=c.path("binding").path("type").asText();if(type.equals("workflow")){JsonNode status=executions.workflowStatus(str(r,"owner_id"),target),remote=status.path("task");if(remote.isMissingNode()){if(status.path("status").asText().equals("failed"))state(id,"failed",null,"工作流任务创建失败");return;}String next=remote.path("state").asText();if(next.equals("succeeded")){JsonNode result=executions.workflowResult(str(r,"owner_id"),c,status);schema(c.path("outputSchema"),result);state(id,"succeeded",result,null);}else if(Arrays.asList("failed","cancelled","waiting_manual").contains(next))state(id,next.equals("waiting_manual")?"interrupted":next,null,next.equals("waiting_manual")?"工作流等待人工处理":null);}
            else{JsonNode detail=json.valueToTree(executions.tasks.detail(str(r,"owner_id"),target));recordUsage(id,detail.path("usage"));JsonNode runs=executions.tasks.runs(str(r,"owner_id"),target).path("items");if(runs.isMissingNode())runs=executions.tasks.runs(str(r,"owner_id"),target);JsonNode latest=null;for(JsonNode run:runs)latest=run;if(latest==null)return;String next=latest.path("status").asText();if(next.equals("completed")){Map<String,Object> fresh=row(id);require(fresh.get("submitted_json")!=null,422,"智能体结束但未提交合格的结构化结果");JsonNode result=parse(json,fresh.get("submitted_json"));schema(c.path("outputSchema"),result);state(id,"succeeded",result,null);}else if(Arrays.asList("waiting_input","interrupted","failed","cancelled").contains(next))state(id,next,null,null);else if(str(r,"state").equals("waiting_input"))state(id,"running",null,null);}
        }catch(ApiException e){state(id,e.status>=500?"interrupted":"failed",null,e.getMessage());}catch(Exception e){state(id,"interrupted",null,"读取执行状态失败，请核对原操作");}}
    private void recordUsage(String id,JsonNode usage){if(!usage.isObject())return;ObjectNode safe=json.createObjectNode();for(String field:Arrays.asList("totalTokens","inputTokens","outputTokens","cacheReadTokens","cacheWriteTokens","callCount","unknownCalls","pendingCalls","usageKnown","unavailable"))if(usage.has(field))safe.set(field,usage.get(field));if(safe.has("totalTokens"))db.update("UPDATE nw_service_operation SET usage_json=? WHERE id=?",safe.toString(),id);}
    @org.springframework.beans.factory.annotation.Value("${nebu.workbench-services.polling-enabled:true}") private boolean polling;
    @Scheduled(fixedDelay=1000) public void tick(){if(polling)process();}
    public void process(){if(!services.available)return;for(Map<String,Object> r:db.rows("SELECT id,state,updated_at FROM nw_service_operation WHERE state IN ('pending','dispatching','running','waiting_input') ORDER BY created_at LIMIT 30")){String id=str(r,"id");if(str(r,"state").equals("pending"))dispatch(id);else if(str(r,"state").equals("dispatching")){Object time=r.get("updated_at");if(time instanceof java.util.Date&&System.currentTimeMillis()-((java.util.Date)time).getTime()>60000)state(id,"interrupted",null,"派发结果待核对");}else refresh(id);}}
    public Object command(ServiceAccess.Principal p,String wb,String id,JsonNode body,String key){requestKey(key);Map<String,Object> r=row(id);JsonNode c=authorized(p,wb,r);String action=text(body,"action",32);if(action.equals("reconcile")){require(str(r,"state").equals("interrupted"),409,"仅核对中断操作");if(str(r,"target_id").isEmpty()){require(!c.path("binding").path("type").asText().equals("platform"),409,"平台写入结果需要人工核对");db.update("UPDATE nw_service_operation SET state='pending' WHERE id=? AND state='interrupted'",id);dispatch(id);}else{state(id,"running",null,null);refresh(id);}return get(p,wb,id);}
        require(!Arrays.asList("succeeded","failed","cancelled").contains(str(r,"state")),409,"操作已经结束");require(Arrays.asList("cancel","input","resume").contains(action),422,"未知执行控制");String target=str(r,"target_id");if(target.isEmpty()){require(action.equals("cancel")&&str(r,"state").equals("pending"),409,"执行尚未确认，请先核对");require(db.update("UPDATE nw_service_operation SET state='cancelled',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND state='pending'",id)==1,409,"派发已开始，请重新读取后取消");event(id);return get(p,wb,id);}
        if(c.path("binding").path("type").asText().equals("workflow")){require(!action.equals("input"),422,"Workflow 当前不支持交互输入");JsonNode remote=executions.workflowStatus(p.owner,target).path("task");executions.workflow.control(p.owner,target,action.equals("cancel")?"cancel":"resume",json.valueToTree(map("expected_version",remote.path("version").asInt())),"svc-"+hash(key).substring(0,40));}
        else{JsonNode runs=executions.tasks.runs(p.owner,target);if(runs.has("items"))runs=runs.path("items");JsonNode latest=null;for(JsonNode run:runs)latest=run;require(latest!=null,409,"运行尚未创建");executions.tasks.command(p.owner,target,latest.path("id").asText(),json.valueToTree(map("type",action.equals("input")?"steer":action,"content",body.path("content").asText(""))),key);}
        if(action.equals("resume"))state(id,"running",null,null);return get(p,wb,id);
    }
    public void authorizeRun(Map<String,Object> task,JsonNode run){if(!run.path("manifest").has("service"))return;Map<String,Object> r=db.one("SELECT * FROM nw_service_operation WHERE target_id=? AND owner_id=?",task.get("id"),run.path("ownerId").asText());require(r!=null&&run.path("manifest").path("service").path("operationId").asText().equals(str(r,"id")),403,"服务执行身份不匹配");require(Arrays.asList("dispatching","running","waiting_input").contains(str(r,"state")),403,"服务操作已停止或等待核对");authorized(current(r),str(r,"workbench_id"),r);}
    /** Called only after AgentBridge has authenticated the live engine Run. */
    public boolean applyManifest(String taskId,ObjectNode manifest){Map<String,Object> r=db.one("SELECT * FROM nw_service_operation WHERE target_id=? AND owner_id=?",taskId,manifest.path("ownerId").asText());if(r==null)return false;JsonNode c=authorized(current(r),str(r,"workbench_id"),r);require(c.path("binding").path("type").asText().equals("agent"),403,"服务执行类型不匹配");JsonNode snapshot=parse(json,services.release(str(r,"owner_id"),str(r,"workbench_id"),str(r,"release_id")).get("execution_json")).path(str(r,"capability_key"));for(String field:Arrays.asList("instructions","files","skills","mcp","model","experts","knowledgeRefs","knowledgeReferences","primaryExpertId","platformMcp","databaseReferences","workbenchId"))if(snapshot.has(field))manifest.set(field,snapshot.get(field));if(!snapshot.has("platformMcp"))manifest.remove("platformMcp");if(!snapshot.has("databaseReferences"))manifest.remove("databaseReferences");for(JsonNode expert:snapshot.path("experts"))require(executions.experts.visibleExpert(str(r,"owner_id"),expert.path("id").asText())!=null,403,"服务专家授权已撤销");manifest.set("service",json.valueToTree(map("operationId",r.get("id"),"releaseId",r.get("release_id"),"outputSchema",c.path("outputSchema"))));return true;}
    public ArrayNode tools(boolean result){ArrayNode out=json.createArrayNode();if(!services.available)return out;out.add(tool("service_draft_get","读取当前工作台服务草稿","draft.get",map("type","object","properties",map(),"additionalProperties",false),"read"));out.add(tool("service_draft_save","保存服务草稿；不能发布","draft.save",map("type","object","properties",map("revision",map("type","integer"),"definition",map("type","object")),"required",Arrays.asList("revision","definition"),"additionalProperties",false),"idempotent"));out.add(tool("service_page_register","将当前任务 HTML 成果登记为页面草稿；不能发布","page.register",map("type","object","properties",map("revision",map("type","integer"),"page",map("type","object"),"artifactId",map("type","string"),"version",map("type","integer"),"html",map("type","string")),"required",Arrays.asList("revision","page"),"additionalProperties",false),"idempotent"));if(result)out.add(tool("service_result_submit","提交服务最终结构化结果，必须符合本轮输出 Schema","result.submit",map("type","object","properties",map("result",map()),"required",Collections.singletonList("result"),"additionalProperties",false),"idempotent"));return out;}
    private JsonNode tool(String name,String description,String operation,Object parameters,String replay){return json.valueToTree(map("name",name,"description",description,"capability","service","operation",operation,"parameters",parameters,"required",false,"replay",replay));}
    public Object agentTool(String owner,Map<String,Object> task,JsonNode run,String operation,JsonNode args){require(!run.hasNonNull("parentRunId"),403,"服务草稿与结果仅允许主任务提交");String project=str(task,"project_id"),wb=str(executions.tasks.project(owner,project,false),"workbench_id");switch(operation){case "draft.get":ObjectNode view=json.valueToTree(services.get(owner,wb));view.put("projectId",project);view.put("workbenchId",wb);return view;case "draft.save":return services.save(owner,wb,args);case "page.register":ObjectNode asset=args.has("artifactId")?json.valueToTree(map("projectId",project,"artifactId",args.path("artifactId"),"version",args.path("version"))):json.valueToTree(map("html",args.path("html")));JsonNode stored=json.valueToTree(services.assetAdd(owner,wb,asset,json.valueToTree(map("projectId",project,"taskId",task.get("id"),"runId",run.path("id")))));ObjectNode definition=(ObjectNode)json.valueToTree(services.get(owner,wb)).path("draft");ObjectNode page=args.path("page").deepCopy();page.put("assetId",stored.path("id").asText());ArrayNode pages=definition.withArray("pages");for(int i=pages.size()-1;i>=0;i--)if(pages.get(i).path("key").equals(page.path("key")))pages.remove(i);pages.add(page);return services.save(owner,wb,json.valueToTree(map("revision",args.path("revision"),"definition",definition)));
        case "result.submit":Map<String,Object> r=db.one("SELECT * FROM nw_service_operation WHERE target_id=? AND owner_id=?",task.get("id"),owner);require(r!=null,403,"无效服务结果上下文");JsonNode c=authorized(current(r),wb,r);require(run.path("manifest").path("service").path("operationId").asText().equals(str(r,"id")),403,"服务执行不匹配");require(args.has("result"),422,"需要 result");schema(c.path("outputSchema"),args.get("result"));db.update("UPDATE nw_service_operation SET submitted_json=? WHERE id=? AND state IN ('dispatching','running','waiting_input')",args.get("result").toString(),r.get("id"));return map("accepted",true,"operationId",r.get("id"));default:throw new ApiException(422,"未知服务工具");}}
    Map<String,Object> instance(ServiceAccess.Principal p,String wb,String id){Map<String,Object> r=db.one("SELECT * FROM nw_service_page_instance WHERE id=? AND owner_id=? AND workbench_id=?",id,p.owner,wb);require(r!=null&&(p.browser||p.app.equals(str(r,"app_id"))),404,"页面实例不存在");p.allow(wb,"pages",str(r,"page_key"));p.allow(wb,"projects",str(r,"project_id"));services.project(p.owner,wb,str(r,"project_id"),false);JsonNode definition=parse(json,services.active(p,wb,str(r,"release_id")).get("definition_json")),page=item(definition,"pages",str(r,"page_key"));if(page.has("projectIds"))require(contains(page.path("projectIds"),str(r,"project_id")),403,"页面未授权此项目");return r;}
    public Object createInstance(ServiceAccess.Principal p,String wb,String page,JsonNode body,String key){requestKey(key);p.allow(wb,"pages",page);String project=text(body,"projectId",128);p.allow(wb,"projects",project);services.project(p.owner,wb,project,false);String id="sp-"+hash(p.owner+":"+p.app+":"+wb+":"+key).substring(0,48),digest=hash(page+":"+fingerprint(json,body));Map<String,Object> old=db.one("SELECT * FROM nw_service_page_instance WHERE id=?",id);if(old!=null){require(digest.equals(str(old,"request_hash")),409,"页面实例请求编号冲突");return page(p,wb,id);}
        Map<String,Object> release=services.active(p,wb,body.path("releaseId").asText(""));JsonNode definition=parse(json,release.get("definition_json")),definitionPage=item(definition,"pages",page);if(definitionPage.has("projectIds"))require(contains(definitionPage.path("projectIds"),project),403,"页面未授权此项目");for(JsonNode capability:definitionPage.path("capabilities")){p.allow(wb,"capabilities",capability.asText());require(contains(item(definition,"capabilities",capability.asText()).path("projectIds"),project),403,"页面项目未授权");}JsonNode context=body.path("context").isObject()?body.path("context"):json.createObjectNode();require(context.toString().length()<64000,413,"页面上下文过大");db.update("INSERT INTO nw_service_page_instance(id,owner_id,workbench_id,app_id,release_id,page_key,project_id,context_json,state_json,request_key,request_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",id,p.owner,wb,p.app,release.get("id"),page,project,context.toString(),"{}",key,digest);require(digest.equals(str(instance(p,wb,id),"request_hash")),409,"页面实例请求编号冲突");return page(p,wb,id);}
    public Object page(ServiceAccess.Principal p,String wb,String id){Map<String,Object> r=instance(p,wb,id);JsonNode definition=parse(json,services.release(p.owner,wb,str(r,"release_id")).get("definition_json")),page=item(definition,"pages",str(r,"page_key"));for(JsonNode c:page.path("capabilities"))p.allow(wb,"capabilities",c.asText());ObjectNode display=page.deepCopy();if(!p.browser)display.remove("projectIds");return map("id",id,"workbenchId",wb,"releaseId",r.get("release_id"),"page",display,"projectId",r.get("project_id"),"context",parse(json,r.get("context_json")),"state",parse(json,r.get("state_json")),"revision",r.get("revision"),"html",services.asset(p.owner,wb,page.path("assetId").asText()).get("html"));}
    public Object saveState(ServiceAccess.Principal p,String wb,String id,JsonNode body){Map<String,Object> r=instance(p,wb,id);require(body.has("state")&&body.path("state").toString().length()<=64000,422,"页面状态须小于64 KiB");require(db.update("UPDATE nw_service_page_instance SET state_json=?,revision=revision+1 WHERE id=? AND revision=?",body.path("state").toString(),id,body.path("revision").asLong(-1))==1,409,"页面状态已更新，请重新读取");return page(p,wb,id);}
}
